package com.locallaunch.controller;
import com.locallaunch.dto.BusinessUpdateRequest; import com.locallaunch.entity.BusinessUpdate; import com.locallaunch.service.BusinessUpdateService; import jakarta.validation.Valid; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/updates") public class BusinessUpdateController { private final BusinessUpdateService service; public BusinessUpdateController(BusinessUpdateService s){service=s;} @PostMapping("/{businessId}") public ResponseEntity<BusinessUpdate> add(@PathVariable Long businessId,@Valid @RequestBody BusinessUpdateRequest req){return ResponseEntity.ok(service.add(businessId,req));} @GetMapping("/{businessId}") public List<BusinessUpdate> list(@PathVariable Long businessId){return service.list(businessId);} @DeleteMapping("/{id}") public ResponseEntity<String> delete(@PathVariable Long id){service.delete(id);return ResponseEntity.ok("Update deleted successfully");} }
